import json
import uuid
from pathlib import Path

def md_cell(text):
    return {'cell_type': 'markdown', 'id': uuid.uuid4().hex[:8], 'metadata': {}, 'source': [line + '\n' for line in text.split('\n')]}

def code_cell(code):
    return {'cell_type': 'code', 'execution_count': None, 'id': uuid.uuid4().hex[:8], 'metadata': {}, 'outputs': [], 'source': [line + '\n' for line in code.split('\n')]}

def create_notebook(cells, filepath):
    nb = {'cells': cells, 'metadata': {'kernelspec': {'display_name': 'Python 3', 'language': 'python', 'name': 'python3'}, 'language_info': {'name': 'python', 'version': '3.11'}}, 'nbformat': 4, 'nbformat_minor': 5}
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(nb, f, indent=2)
    print(f'Created: {filepath} with {len(cells)} cells')
